#!/bin/bash
# Uninstall script for Streamlabs Desktop
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Streamlabs Desktop..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Streamlabs Desktop if running..."
pkill -f "Streamlabs Desktop" 2>/dev/null || true

# Remove /Applications/Streamlabs Desktop.app
echo "Removing /Applications/Streamlabs Desktop.app..."
if [ -d "/Applications/Streamlabs Desktop.app" ]; then
    rm -rf "/Applications/Streamlabs Desktop.app" 2>/dev/null || true
elif [ -f "/Applications/Streamlabs Desktop.app" ]; then
    rm -f "/Applications/Streamlabs Desktop.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/slobs-client
echo "Removing $HOME/Library/Application Support/slobs-client..."
if [ -d "$HOME/Library/Application Support/slobs-client" ]; then
    rm -rf "$HOME/Library/Application Support/slobs-client" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/slobs-client" ]; then
    rm -f "$HOME/Library/Application Support/slobs-client" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/slobs-plugins
echo "Removing $HOME/Library/Application Support/slobs-plugins..."
if [ -d "$HOME/Library/Application Support/slobs-plugins" ]; then
    rm -rf "$HOME/Library/Application Support/slobs-plugins" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/slobs-plugins" ]; then
    rm -f "$HOME/Library/Application Support/slobs-plugins" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/com.streamlabs.slobs.plist
echo "Removing $HOME/Library/Preferences/com.streamlabs.slobs.plist..."
if [ -d "$HOME/Library/Preferences/com.streamlabs.slobs.plist" ]; then
    rm -rf "$HOME/Library/Preferences/com.streamlabs.slobs.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/com.streamlabs.slobs.plist" ]; then
    rm -f "$HOME/Library/Preferences/com.streamlabs.slobs.plist" 2>/dev/null || true
fi

# Remove $HOME/Library/Saved Application State/com.streamlabs.slobs.savedState
echo "Removing $HOME/Library/Saved Application State/com.streamlabs.slobs.savedState..."
if [ -d "$HOME/Library/Saved Application State/com.streamlabs.slobs.savedState" ]; then
    rm -rf "$HOME/Library/Saved Application State/com.streamlabs.slobs.savedState" 2>/dev/null || true
elif [ -f "$HOME/Library/Saved Application State/com.streamlabs.slobs.savedState" ]; then
    rm -f "$HOME/Library/Saved Application State/com.streamlabs.slobs.savedState" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
